                + cos(worldUV.y * freq * 0.8 + t1) * 0.4
                + cos((worldUV.x - worldUV.y) * freq * 1.0 + t3) * 0.3
                + cos(worldUV.x * freq * 1.8 + t1 * 1.3) * 0.2;

